import{_ as n,a0 as p,w as d,s as r,ao as o,I as a,a1 as e,A as l,x as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"fold 命令入门示例教程 | LCTT x X-CMD","titleTemplate":false,"description":"fold 命令入门示例教程 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"fold 命令入门示例教程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"fold 命令入门示例教程 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180111 The Fold Command Tutorial With Examples For Beginners","title":"fold 命令入门示例教程","tag":"201803","desc":""},"relativePath":"201803/20180111 The Fold Command Tutorial With Examples For Beginners.md","filePath":"[post].md"}'),h={name:"201803/20180111 The Fold Command Tutorial With Examples For Beginners.md"};function g(c,t,u,m,f,k){const i=p("Link");return d(),r("div",null,[t[14]||(t[14]=o('<h1 id="fold-命令入门示例教程" tabindex="-1">fold 命令入门示例教程 <a class="header-anchor" href="#fold-命令入门示例教程" aria-label="Permalink to “fold 命令入门示例教程”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/01/Fold-Command-2-720x340.png" alt=""></p><p>你有没有发现自己在某种情况下想要折叠或中断命令的输出，以适应特定的宽度？在运行虚拟机的时候，我遇到了几次这种的情况，特别是没有 GUI 的服务器。 以防万一，如果你想限制一个命令的输出为一个特定的宽度，现在看看这里！ <code>fold</code> 命令在这里就能派的上用场了！ <code>fold</code> 命令会以适合指定的宽度调整输入文件中的每一行，并将其打印到标准输出。</p><p>在这个简短的教程中，我们将看到 <code>fold</code> 命令的用法，带有实例。</p><h3 id="fold-命令示例教程" tabindex="-1">fold 命令示例教程 <a class="header-anchor" href="#fold-命令示例教程" aria-label="Permalink to “fold 命令示例教程”">​</a></h3><p><code>fold</code> 命令是 GNU coreutils 包的一部分，所以我们不用为安装的事情烦恼。</p><p><code>fold</code> 命令的典型语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold [OPTION]... [FILE]...</span></span></code></pre></div><p>请允许我向您展示一些示例，以便您更好地了解 <code>fold</code> 命令。 我有一个名为 <code>linux.txt</code> 文件，内容是随机的。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-1.png" alt=""></p><p>要将上述文件中的每一行换行为默认宽度，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold linux.txt</span></span></code></pre></div><p>每行 80 列是默认的宽度。 这里是上述命令的输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-2.png" alt=""></p><p>正如你在上面的输出中看到的，<code>fold</code> 命令已经将输出限制为 80 个字符的宽度。</p><p>当然，我们可以指定您的首选宽度，例如 50，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold -w50 linux.txt</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-3-1.png" alt=""></p><p>我们也可以将输出写入一个新的文件，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold -w50 linux.txt &gt; linux1.txt</span></span></code></pre></div><p>以上命令将把 <code>linux.txt</code> 的行宽度改为 50 个字符，并将输出写入到名为 <code>linux1.txt</code> 的新文件中。</p><p>让我们检查一下新文件的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat linux1.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-4.png" alt=""></p><p>你有没有注意到前面的命令的输出？ 有些词在行之间被中断。 为了解决这个问题，我们可以使用 <code>-s</code> 标志来在空格处换行。</p><p>以下命令将给定文件中的每行调整为宽度 50，并在空格处换到新行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold -w50 -s linux.txt</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-5-1.png" alt=""></p><p>看清楚了吗？ 现在，输出很清楚。 换到新行中的单词都是用空格隔开的，所在行单词的长度大于 50 的时候就会被调整到下一行。</p><p>在所有上面的例子中，我们用列来限制输出宽度。 但是，我们可以使用 <code>-b</code> 选项将输出的宽度强制为指定的字节数。 以下命令以 20 个字节中断输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold -b20 linux.txt</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-6-1.png" alt=""></p><p>另请阅读：</p>',36)),a("ul",null,[a("li",null,[e(i,{href:"https://www.ostechnix.com/uniq-command-tutorial-examples-beginners/"},{default:l(()=>[...t[0]||(t[0]=[s("Uniq 命令入门级示例教程",-1)])]),_:1})])]),t[15]||(t[15]=o('<p>有关更多详细信息，请参阅 man 手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man fold</span></span></code></pre></div><p>这些就是所有的内容了。 您现在知道如何使用 <code>fold</code> 命令以适应特定的宽度来限制命令的输出。 我希望这是有用的。 我们将每天发布更多有用的指南。 敬请关注！</p><p>干杯!</p><hr>',5)),a("p",null,[t[2]||(t[2]=s("via: ",-1)),e(i,{href:"https://www.ostechnix.com/fold-command-tutorial-examples-beginners/"},{default:l(()=>[...t[1]||(t[1]=[s("https://www.ostechnix.com/fold-command-tutorial-examples-beginners/",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=s("作者：",-1)),e(i,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...t[3]||(t[3]=[s("SK",-1)])]),_:1}),t[7]||(t[7]=s(" 译者：",-1)),e(i,{href:"https://github.com/Flowsnow"},{default:l(()=>[...t[4]||(t[4]=[s("Flowsnow",-1)])]),_:1}),t[8]||(t[8]=s(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[5]||(t[5]=[s("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[9]||(t[9]=[s("LCTT",-1)])]),_:1}),t[12]||(t[12]=s(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:l(()=>[...t[10]||(t[10]=[s("Linux中国",-1)])]),_:1}),t[13]||(t[13]=s(" 荣誉推出",-1))])])}const C=n(h,[["render",g]]);export{w as __pageData,C as default};
